export const blocks: readonly LiturgyBlock[] = [
  {"id": "cu-pon-0001", "section": "service", "who": "reader", "text": "ВО СВЯТУЮ И ВЕЛИКУЮ НЕДЕЛЮ ПАСХИ НА ВЕЛИКОЙ ВЕЧЕРНЕ По 9-м часе, во светильничном, облачится настоятель во всю священную одежду. И став пред святою трапезою с кадильницею, знаменует крестовидно, и возглашает глаголя:"},
  {"id": "cu-pon-0002", "section": "service", "who": "reader", "text": "Благослове́н Бог наш всегда́, ны́не и при́сно и во ве́ки веко́в."},
  {"id": "cu-pon-0003", "section": "service", "who": "rubric", "text": "И нам отвещающим:"},
  {"id": "cu-pon-0004", "section": "service", "who": "reader", "text": "Ами́нь."},
  {"id": "cu-pon-0005", "section": "service", "who": "rubric", "text": "И той начинает:"},
  {"id": "cu-pon-0006", "section": "service", "who": "reader", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pon-0007", "section": "service", "who": "rubric", "text": "Трижды. И мы тойжде отвещаем трижды."},
  {"id": "cu-pon-0008", "section": "service", "who": "reader", "text": "И глаголет настоятель преждереченныя стихи: Первый стих:"},
  {"id": "cu-pon-0009", "section": "service", "who": "reader", "text": "Да воскре́снет Бог, и расточа́тся врази́ Его́, / и да бежа́т от Лица́ Его́ ненави́дящии Его́."},
  {"id": "cu-pon-0010", "section": "service", "who": "rubric", "text": "И на кийждо стих мы поем тропарь:"},
  {"id": "cu-pon-0011", "section": "service", "who": "reader", "text": "Христо́с воскре́се из ме́ртвых:"},
  {"id": "cu-pon-0012", "section": "service", "who": "rubric", "text": "Весь по единожды."},
  {"id": "cu-pon-0013", "section": "service", "who": "rubric", "text": "Вторый стих:"},
  {"id": "cu-pon-0014", "section": "service", "who": "reader", "text": "Я́ко исчеза́ет дым, да исче́знут, / я́ко та́ет воск от лица́ огня́. Тропарь:"},
  {"id": "cu-pon-0015", "section": "service", "who": "reader", "text": "Христо́с воскре́се: единожды. Третий стих:"},
  {"id": "cu-pon-0016", "section": "service", "who": "reader", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся. Тропарь:"},
  {"id": "cu-pon-0017", "section": "service", "who": "reader", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-pon-0018", "section": "service", "who": "rubric", "text": "Четвертый стих:"},
  {"id": "cu-pon-0019", "section": "service", "who": "reader", "text": "Сей день, его́же сотвори́ Госпо́дь, / возра́дуемся и возвесели́мся в онь. Тропарь:"},
  {"id": "cu-pon-0020", "section": "service", "who": "reader", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-pon-0021", "section": "service", "who": "reader", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху. Тропарь:"},
  {"id": "cu-pon-0022", "section": "service", "who": "reader", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-pon-0023", "section": "service", "who": "reader", "text": "И ны́не и при́сно и во ве́ки веко́в. Ами́нь. Тропарь:"},
  {"id": "cu-pon-0024", "section": "service", "who": "reader", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-pon-0025", "section": "service", "who": "rubric", "text": "Таже настоятель:"},
  {"id": "cu-pon-0026", "section": "service", "who": "reader", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в. И мы конец:"},
  {"id": "cu-pon-0027", "section": "service", "who": "reader", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pon-0028", "section": "service", "who": "rubric", "text": "Таже ектениа великая от диакона:"},
  {"id": "cu-pon-0029", "section": "service", "who": "deacon", "text": "Ми́ром Го́споду помо́лимся."},
  {"id": "cu-pon-0030", "section": "service", "who": "rubric", "text": "Подобает ведати, яко по внегда начати иерею, кадит святую трапезу по обычаю и весь олтарь, вечер, на"},
  {"id": "cu-pon-0031", "section": "service", "who": "deacon", "text": "Го́споди воззва́х:"},
  {"id": "cu-pon-0032", "section": "service", "who": "rubric", "text": "на Утрени, в начале канона исходит и кадит храм и лики и братию по обыкновенному чину."},
  {"id": "cu-pon-0033", "section": "service", "who": "choir", "text": "Посем, Го́споди воззва́х: поем во глас 2. Поставим стихов 6. И поем стихиры воскресны 3, глас 2. Стих:"},
  {"id": "cu-pon-0034", "section": "service", "who": "choir", "text": "А́ще беззако́ния на́зриши, Го́споди, Го́споди, кто постои́т? Я́ко у Тебе́ очище́ние есть."},
  {"id": "cu-pon-0035", "section": "service", "who": "choir", "text": "Пре́жде век от Отца́ ро́ждшемуся Бо́жию Сло́ву, / вопло́щшемуся от Де́вы Мари́и, / прииди́те, поклони́мся. / Крест бо претерпе́в, / погребе́нию предаде́ся, я́ко Сам восхоте́, / и воскре́се из ме́ртвых, / спасе́ мя заблужда́ющаго челове́ка. Стих:"},
  {"id": "cu-pon-0036", "section": "service", "who": "choir", "text": "И́мене ра́ди Твоего́ потерпе́х Тя, Го́споди, потерпе́ душа́ моя́ в сло́во Твое́, упова́ душа́ моя́ на Го́спода."},
  {"id": "cu-pon-0037", "section": "service", "who": "choir", "text": "Христо́с Спас наш, / е́же на ны рукописа́ние пригвозди́в на Кресте́ загла́ди, / и сме́рную держа́ву упраздни́, / поклоня́емся Его́ тридне́вному Воскресе́нию. Стих:"},
  {"id": "cu-pon-0038", "section": "service", "who": "choir", "text": "От стра́жи у́тренния до но́щи, от стра́жи у́тренния да упова́ет Изра́иль на Го́спода."},
  {"id": "cu-pon-0039", "section": "service", "who": "choir", "text": "Со Арха́нгелы воспои́м Христо́во Воскресе́ние, / Той бо есть Изба́витель и Спас душ на́ших, / и в сла́ве стра́шней и кре́пцей си́ле, / па́ки гряде́т суди́ти мiру, его́же созда́."},
  {"id": "cu-pon-0040", "section": "service", "who": "choir", "text": "И восточны (Анатолиевы) 3. Стих:"},
  {"id": "cu-pon-0041", "section": "service", "who": "choir", "text": "Я́ко у Го́спода ми́лость, и мно́гое у Него́ избавле́ние, и Той изба́вит Изра́иля от всех беззако́ний eго́."},
  {"id": "cu-pon-0042", "section": "service", "who": "choir", "text": "Тебе́ Распе́ншагося и Погребе́ннаго, / А́нгел пропове́да Влады́ку, и глаго́лаше жена́м: / прииди́те ви́дите, иде́же лежа́ше Госпо́дь, / воскре́се бо, я́коже рече́, я́ко Всеси́лен. / Те́мже Тебе́ поклоня́емся, Еди́ному Безсме́ртному, / Жизнода́вче Христе́, поми́луй нас. Стих:"},
  {"id": "cu-pon-0043", "section": "service", "who": "choir", "text": "Хвали́те Го́спода вси язы́цы, похвали́те Его́ вси лю́дие."},
  {"id": "cu-pon-0044", "section": "service", "who": "choir", "text": "Кресто́м Твои́м упраздни́л еси́, / ю́же от дре́ва кля́тву, / погребе́нием Твои́м умертви́л еси́ сме́рти держа́ву, / воста́нием же Твои́м просвети́л еси́ род челове́ческий. / Сего́ ра́ди вопие́м Ти: / Благоде́телю Христе́ Бо́же наш, сла́ва Тебе́. Стих:"},
  {"id": "cu-pon-0045", "section": "service", "who": "choir", "text": "Я́ко утверди́ся ми́лость Его́ на нас, и и́стина Госпо́дня пребыва́ет во век."},
  {"id": "cu-pon-0046", "section": "service", "who": "choir", "text": "Отверзо́шася Тебе́, Го́споди, / стра́хом врата́ сме́ртная, / вра́тницы же а́довы ви́девше Тя, убоя́шася, / врата́ бо ме́дная сокруши́л еси́, / и вереи́ желе́зныя стерл еси́, / и изве́л еси́ нас от тмы и се́ни сме́ртныя, / и у́зы на́ша растерза́л еси́."},
  {"id": "cu-pon-0047", "section": "service", "who": "choir", "text": "Слава: Спаси́тельную песнь пою́ще, от уст возсле́м. / Прииди́те вси в дому́ Госпо́днем припаде́м, глаго́люще: / на дре́ве Распны́йся, и из ме́ртвых Воскресы́й, / и Сый в не́дрех О́тчих, / очи́сти грехи́ на́ша."},
  {"id": "cu-pon-0048", "section": "service", "who": "choir", "text": "И ныне, Богородичен: Пре́йде сень зако́нная, / благода́ти прише́дши, / я́коже бо купина́ не сгара́ше опаля́ема, / та́ко Де́ва родила́ еси́ / и Де́ва пребыла́ еси́. / Вме́сто столпа́ о́гненнаго, / пра́ведное возсия́ Со́лнце, / вме́сто Моисе́я, Христо́с, / Спасе́ние душ на́ших."},
  {"id": "cu-pon-0049", "section": "service", "who": "rubric", "text": "Вход со Евангелием."},
  {"id": "cu-pon-0050", "section": "service", "who": "choir", "text": "Све́те ти́хий:"},
  {"id": "cu-pon-0051", "section": "service", "who": "choir", "text": "Таже, прокимен великий, глас 7: Кто Бог ве́лий, я́ко Бог наш? / Ты еси́ Бог творя́й чудеса́. Стих 1:"},
  {"id": "cu-pon-0052", "section": "service", "who": "choir", "text": "Сказа́л еси́ в лю́дех си́лу Твою́. Стих 2:"},
  {"id": "cu-pon-0053", "section": "service", "who": "choir", "text": "И рех: ны́не нача́х, сия́ изме́на десни́цы Вы́шняго. Стих 3:"},
  {"id": "cu-pon-0054", "section": "service", "who": "choir", "text": "Помяну́х дела́ Госпо́дня, я́ко помяну́ от начала чудеса́ Твоя́. И паки:"},
  {"id": "cu-pon-0055", "section": "service", "who": "choir", "text": "Кто Бог ве́лий, я́ко Бог наш? Ты еси́ Бог творя́й чудеса́."},
  {"id": "cu-pon-0056", "section": "service", "who": "rubric", "text": "По прокимне же возглашает диакон:"},
  {"id": "cu-pon-0057", "section": "service", "who": "deacon", "text": "И о сподо́битися нам слы́шанию свята́го Ева́нгелиа, Го́спода Бо́га мо́лим."},
  {"id": "cu-pon-0058", "section": "service", "who": "choir", "text": "Го́споди поми́луй. Трижды."},
  {"id": "cu-pon-0059", "section": "service", "who": "choir", "text": "Посем чтет Евангелие настоятель во олтари."},
  {"id": "cu-pon-0060", "section": "service", "who": "choir", "text": "Евангелие от Иоанна, зачало 65."},
  {"id": "cu-pon-0061", "section": "service", "who": "choir", "text": "Су́щу по́зде в день той во еди́ну от суббо́т, и две́рем затворе́нным, иде́же бя́ху ученицы́ Его́ со́брани, стра́ха ра́ди иуде́йска, прии́де Иису́с и ста посреде́, и глаго́ла им: мир вам. И сие́ рек, показа́ им ру́це и но́зе, и ре́бра Своя́. Возра́довашася у́бо ученицы́, ви́девше Го́спода. Рече́ же им Иису́с па́ки: мир вам. Я́коже посла́ Мя Оте́ц, и Аз посыла́ю вы. И сие́ рек, ду́ну и глаго́ла им: приими́те Дух Свят. И́мже отпустите́ грехи́, отпу́стятся им, и и́мже держите́, держа́тся. Фома́ же, еди́н от обоюна́десяте, глаго́лемый Близне́ц, не бе ту с ни́ми, егда́ прии́де Иису́с. Глаго́лаху же ему́ друзи́и ученицы: ви́дехом Го́спода. Он же рече́ им: а́ще не ви́жу на руку́ Его́ я́звы гвозди́нныя, и вложу́ пе́рста моего́ в я́звы гвозди́нныя, и вложу́ ру́ку мою́ в ре́бра Его́, не иму́ ве́ры."},
  {"id": "cu-pon-0062", "section": "service", "who": "choir", "text": "Сла́ва Тебе́, Го́споди, сла́ва Тебе́."},
  {"id": "cu-pon-0063", "section": "service", "who": "rubric", "text": "Посем ектениа:"},
  {"id": "cu-pon-0064", "section": "service", "who": "choir", "text": "Рцем вси: и Сподо́би, Го́споди, в ве́чер сей: Таже:"},
  {"id": "cu-pon-0065", "section": "service", "who": "choir", "text": "Испо́лним вече́рнюю моли́тву:"},
  {"id": "cu-pon-0066", "section": "service", "who": "choir", "text": "И по возгласе поем стихиру воскресну, глас 2:"},
  {"id": "cu-pon-0067", "section": "service", "who": "choir", "text": "Воскресе́ние Твое́, Христе́ Спа́се, / всю просвети́ вселе́нную, / и призва́л еси́ Твое́ созда́ние, / Всеси́льне Го́споди, сла́ва Тебе́."},
  {"id": "cu-pon-0068", "section": "service", "who": "choir", "text": "Таже стихиры Пасхи, глас 5. Стих:"},
  {"id": "cu-pon-0069", "section": "service", "who": "choir", "text": "Да воскре́снет Бог, / и расточа́тся врази́ Его́."},
  {"id": "cu-pon-0070", "section": "service", "who": "choir", "text": "Па́сха / свяще́нная нам днесь показа́ся; / Па́сха но́ва свята́я; / Па́сха та́инственная; / Па́сха всечестна́я. / Па́сха Христо́с Изба́витель; / Па́сха непоро́чная; / Па́сха вели́кая; / Па́сха ве́рных. / Па́сха две́ри ра́йския нам отверза́ющая. / Па́сха всех освяща́ющая ве́рных. Стих:"},
  {"id": "cu-pon-0071", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, / да исче́знут."},
  {"id": "cu-pon-0072", "section": "service", "who": "choir", "text": "Прииди́те / от виде́ния жены́ благове́стницы, / и Сио́ну рцы́те: / приими́ / от нас ра́дости благове́щения, Воскресе́ния Христо́ва: / красу́йся, лику́й / и ра́дуйся, Иерусали́ме, / Царя́ Христа́ узре́в из гро́ба, / я́ко жениха́ происходя́ща. Стих:"},
  {"id": "cu-pon-0073", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся."},
  {"id": "cu-pon-0074", "section": "service", "who": "choir", "text": "Мироно́сицы жены́, / у́тру глубоку́, / предста́вша гро́бу Живода́вца, / обрето́ша А́нгела / на ка́мени седя́ща, / и той провеща́в им, / си́це глаго́лаше: / что и́щете Жива́го с ме́ртвыми; / что пла́чете Нетле́ннаго во тли? / Ше́дше, пропове́дите ученико́м Его́. Стих:"},
  {"id": "cu-pon-0075", "section": "service", "who": "choir", "text": "Сей день, его́же сотвори Госпо́дь, / возра́дуемся и возвесели́мся в онь."},
  {"id": "cu-pon-0076", "section": "service", "who": "choir", "text": "Па́сха кра́сная, / Па́сха, Госпо́дня Па́сха! / Па́сха всечестна́я / нам возсия́. Па́сха, / ра́достию друг дру́га обы́мем. / О Па́сха! / Избавле́ние ско́рби, / и́бо из гро́ба днесь, / я́ко от черто́га / возсия́в Христо́с, / жены́ ра́дости испо́лни, глаго́ля: / пропове́дите апо́столом."},
  {"id": "cu-pon-0077", "section": "service", "who": "choir", "text": "Слава, и ныне, глас 5: Воскресе́ния день, / и просвети́мся торжество́м, / и друг дру́га обы́мем. / Рцем бра́тие, / и ненави́дящим нас, / прости́м вся Воскресе́нием, / и та́ко возопии́м: / Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в, / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pon-0078", "section": "service", "who": "choir", "text": "Христо́с воскре́се:"},
  {"id": "cu-pon-0079", "section": "service", "who": "rubric", "text": "трижды, кроме конца стихиры."},
  {"id": "cu-pon-0080", "section": "service", "who": "rubric", "text": "Таже диакон:"},
  {"id": "cu-pon-0081", "section": "service", "who": "deacon", "text": "Прему́дрость. Мы же:"},
  {"id": "cu-pon-0082", "section": "service", "who": "deacon", "text": "Благослови́. Настоятель:"},
  {"id": "cu-pon-0083", "section": "service", "who": "deacon", "text": "Сый благослове́н Христо́с Бог наш: И мы:"},
  {"id": "cu-pon-0084", "section": "service", "who": "deacon", "text": "Утверди́, Бо́же:"},
  {"id": "cu-pon-0085", "section": "service", "who": "rubric", "text": "Таже настоятель, вместо: Слава Тебе Христе Боже:"},
  {"id": "cu-pon-0086", "section": "service", "who": "deacon", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в. И мы:"},
  {"id": "cu-pon-0087", "section": "service", "who": "deacon", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pon-0088", "section": "service", "who": "rubric", "text": "И абие глаголет отпуст со Крестом:"},
  {"id": "cu-pon-0089", "section": "service", "who": "deacon", "text": "Христо́с воскресы́й из ме́ртвых:"},
  {"id": "cu-pon-0090", "section": "service", "who": "rubric", "text": "И прочее, якоже изъявися в конец Утрени."},
  {"id": "cu-pon-0091", "section": "service", "who": "rubric", "text": "И целуем святыя иконы. И входим в трапезу, и глаголем:"},
  {"id": "cu-pon-0092", "section": "service", "who": "deacon", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-pon-0093", "section": "service", "who": "deacon", "text": "Сла́ва, и ны́не: Настоятель:"},
  {"id": "cu-pon-0094", "section": "service", "who": "deacon", "text": "Христе́ Бо́же благослови́:"},
  {"id": "cu-pon-0095", "section": "service", "who": "rubric", "text": "По востании же от трапезы, глаголем:"},
  {"id": "cu-pon-0096", "section": "service", "who": "deacon", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-pon-0097", "section": "service", "who": "deacon", "text": "Сла́ва, и ны́не: Настоятель:"},
  {"id": "cu-pon-0098", "section": "service", "who": "deacon", "text": "С на́ми Бог Своею благодатию:"},
  {"id": "cu-pon-0099", "section": "service", "who": "rubric", "text": "И тако творим во всю седмицу Светлую Вечерни последование."},
  {"id": "cu-pon-0100", "section": "service", "who": "deacon", "text": "В ПОНЕДЕЛЬНИК СВЕТЛЫЯ СЕДМИЦЫ НА УТРЕНИ"},
  {"id": "cu-pon-0101", "section": "service", "who": "deacon", "text": "Прежде начала, вжигает кандила и свещи параекклисиарх. Таже клеплет в великий кампан, и в прочия. И собравшимся нам во храм, иерей полагает обычный поклон настоятелю, и отходит во святый олтарь, и взем кадильницу стоит пред святою Трапезою, кроме убо священническия одежды, епитрахилий точию возложь сверх мантии, кадит крестообразно, глаголя:"},
  {"id": "cu-pon-0102", "section": "service", "who": "deacon", "text": "Сла́ва Святе́й, и Единосу́щней, и Животворя́щей, и Нераздели́мей Тро́ице, всегда́, ны́не и при́сно и во ве́ки веко́в."},
  {"id": "cu-pon-0103", "section": "service", "who": "rubric", "text": "И нам отвещающим:"},
  {"id": "cu-pon-0104", "section": "service", "who": "deacon", "text": "Ами́нь."},
  {"id": "cu-pon-0105", "section": "service", "who": "choir", "text": "Начинает настоятель, с прочими служители, велегласно настоящий тропарь, во глас 5:"},
  {"id": "cu-pon-0106", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pon-0107", "section": "service", "who": "choir", "text": "И мы тойжде поем подобне, со сладкопением. Поется же сей тропарь трижды от настоятеля, и трижды от нас."},
  {"id": "cu-pon-0108", "section": "service", "who": "choir", "text": "Таже настоятель глаголет стихи: Первый стих:"},
  {"id": "cu-pon-0109", "section": "service", "who": "choir", "text": "Да воскре́снет Бог, и расточа́тся врази́ Его́, / и да бежа́т от Лица́ Его́ ненави́дящии Его́."},
  {"id": "cu-pon-0110", "section": "service", "who": "rubric", "text": "И на кийждо стих мы поем тропарь весь по единожды:"},
  {"id": "cu-pon-0111", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: Вторый стих:"},
  {"id": "cu-pon-0112", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, да исче́знут, / я́ко та́ет воск от лица́ огня́. Тропарь:"},
  {"id": "cu-pon-0113", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды. Третий стих:"},
  {"id": "cu-pon-0114", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся. Тропарь:"},
  {"id": "cu-pon-0115", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды."},
  {"id": "cu-pon-0116", "section": "service", "who": "rubric", "text": "Четвертый стих:"},
  {"id": "cu-pon-0117", "section": "service", "who": "choir", "text": "Сей день, его́же сотвори́ Госпо́дь, / возра́дуемся и возвесели́мся в онь. Тропарь:"},
  {"id": "cu-pon-0118", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды."},
  {"id": "cu-pon-0119", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху. Тропарь:"},
  {"id": "cu-pon-0120", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды."},
  {"id": "cu-pon-0121", "section": "service", "who": "choir", "text": "И ны́не и при́сно и во ве́ки веко́в. Ами́нь. Тропарь:"},
  {"id": "cu-pon-0122", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды."},
  {"id": "cu-pon-0123", "section": "service", "who": "rubric", "text": "Таже настоятель:"},
  {"id": "cu-pon-0124", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в. И мы конец:"},
  {"id": "cu-pon-0125", "section": "service", "who": "choir", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pon-0126", "section": "service", "who": "choir", "text": "В мирских же храмех облачится иерей в ризы. Таже ектениа великая."},
  {"id": "cu-pon-0127", "section": "service", "who": "rubric", "text": "И по возгласе абие поем канон, ирмос:"},
  {"id": "cu-pon-0128", "section": "service", "who": "choir", "text": "Воскресе́ния день:"},
  {"id": "cu-pon-0129", "section": "service", "who": "rubric", "text": "по дважды, тропари же на 10, с припевы:"},
  {"id": "cu-pon-0130", "section": "service", "who": "choir", "text": "Христо́с воскре́се: В Сла́ва, и ны́не:"},
  {"id": "cu-pon-0131", "section": "service", "who": "rubric", "text": "глаголем Богородичны господина Феофана, и господина Иосифа. Катавасия оба лика вкупе:"},
  {"id": "cu-pon-0132", "section": "service", "who": "choir", "text": "Воскресе́ния день: И последи:"},
  {"id": "cu-pon-0133", "section": "service", "who": "choir", "text": "Христо́с воскре́се:"},
  {"id": "cu-pon-0134", "section": "service", "who": "rubric", "text": "трижды. И глаголем сие во всю седмицу вкупе с ирмосы на 14."},
  {"id": "cu-pon-0135", "section": "service", "who": "choir", "text": "Канон, глас 1. Песнь 1. Ирмос:"},
  {"id": "cu-pon-0136", "section": "service", "who": "choir", "text": "Воскресе́ния день, / просвети́мся, лю́дие. / Па́сха, Госпо́дня Па́сха, / от сме́рти бо к жи́зни, / и от земли́ к небеси́, / Христо́с Бог нас преведе́, / побе́дную пою́щия. Припев:"},
  {"id": "cu-pon-0137", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pon-0138", "section": "service", "who": "choir", "text": "Очи́стим чу́вствия, и у́зрим / непристу́пным све́том / Воскресе́ния, Христа́ блиста́ющася, / и ра́дуйтеся, реку́ща, / я́сно да услы́шим, / побе́дную пою́ще. Припев:"},
  {"id": "cu-pon-0139", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pon-0140", "section": "service", "who": "choir", "text": "Небеса́ у́бо досто́йно да веселя́тся, / земля́ же да ра́дуется, / да пра́зднует же мир, / ви́димый же весь и неви́димый: / Христо́с бо воста́, / весе́лие ве́чное."},
  {"id": "cu-pon-0141", "section": "service", "who": "choir", "text": "Иный канон Богородичен, подобен. Егоже краестрочие на первых тропарех: Феофа́нус. Глас тойже."},
  {"id": "cu-pon-0142", "section": "service", "who": "choir", "text": "Слава: Умерщвле́ния преде́л сломи́ла еси́, / ве́чную жизнь ро́ждшая Христа́, из гро́ба возсия́вшаго днесь, / Де́во Всенепоро́чная, и мир просвети́вшаго."},
  {"id": "cu-pon-0143", "section": "service", "who": "choir", "text": "И ныне: Воскре́сшаго ви́девши Сы́на Твоего́ и Бо́га, / ра́дуйся со апо́столы Богоблагода́тная Чи́стая, / и е́же ра́дуйся пе́рвее, я́ко всех ра́дости вина́, / восприя́ла еси́, Богома́ти Всенепоро́чная."},
  {"id": "cu-pon-0144", "section": "service", "who": "rubric", "text": "Катавасия оба лика вкупе:"},
  {"id": "cu-pon-0145", "section": "service", "who": "choir", "text": "Воскресе́ния день: И последи:"},
  {"id": "cu-pon-0146", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-pon-0147", "section": "service", "who": "choir", "text": "Песнь 3. Ирмос:"},
  {"id": "cu-pon-0148", "section": "service", "who": "choir", "text": "Прииди́те, пи́во пие́м но́вое, / не от ка́мене непло́дна чудоде́емое, / но нетле́ния исто́чник / из гро́ба одожди́вша Христа́, / в Не́мже утвержда́емся. Припев:"},
  {"id": "cu-pon-0149", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pon-0150", "section": "service", "who": "choir", "text": "Ны́не вся испо́лнишася све́та, / не́бо же и земля́, и преиспо́дняя: / да пра́зднует у́бо вся тварь / воста́ние Христо́во, / в не́мже утвержда́ется. Припев:"},
  {"id": "cu-pon-0151", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pon-0152", "section": "service", "who": "choir", "text": "Вчера́ спогребо́хся Тебе́ Христе́, / совостаю́ днесь / воскре́сшу Тебе́, / сраспина́хся Тебе́ вчера́, / Сам мя спросла́ви Спа́се во Ца́рствии Твое́м."},
  {"id": "cu-pon-0153", "section": "service", "who": "choir", "text": "Слава: На нетле́нную жизнь / прихожду́ днесь бла́гостию ро́ждшагося из Тебе́, Чи́стая, / и всем конце́м свет облиста́вшаго."},
  {"id": "cu-pon-0154", "section": "service", "who": "choir", "text": "И ныне: Бо́га, Его́же родила́ еси́ пло́тию, из ме́ртвых, / я́коже рече́, воста́вша ви́девши, Чи́стая, лику́й, / и Сего́ я́ко Бо́га Пречи́стая возвелича́й. Катавасия:"},
  {"id": "cu-pon-0155", "section": "service", "who": "choir", "text": "Прииди́те, пи́во пие́м но́вое: И тропарь:"},
  {"id": "cu-pon-0156", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-pon-0157", "section": "service", "who": "choir", "text": "Таже ектениа."},
  {"id": "cu-pon-0158", "section": "service", "who": "choir", "text": "Ипакои, глас 4:"},
  {"id": "cu-pon-0159", "section": "service", "who": "choir", "text": "Предвари́вшия у́тро я́же о Мари́и, / и обре́тшия ка́мень отвале́н от гро́ба, / слы́шаху от А́нгела: во све́те присносу́щнем Су́щаго, / с ме́ртвыми что и́щете, я́ко челове́ка? / Ви́дите гро́бныя пелены́, тецы́те и ми́ру пропове́дите, / я́ко воста́ Госпо́дь, умертви́вый смерть, / я́ко есть Сын Бо́га, спаса́ющаго род челове́ческий."},
  {"id": "cu-pon-0160", "section": "service", "who": "rubric", "text": "И чтение на 1-ю́ книгу:"},
  {"id": "cu-pon-0161", "section": "service", "who": "reader", "text": "В нача́ле бе Сло́во:"},
  {"id": "cu-pon-0162", "section": "service", "who": "rubric", "text": "от Иоанна, толкование Златоустаго, [от сего бо дне начинаем сию книгу, и даже до Всех святых совершаем]."},
  {"id": "cu-pon-0163", "section": "service", "who": "choir", "text": "Песнь 4. Ирмос:"},
  {"id": "cu-pon-0164", "section": "service", "who": "choir", "text": "На Боже́ственней стра́жи / богоглаго́ливый Авваку́м / да ста́нет с на́ми и пока́жет / светоно́сна А́нгела / я́сно глаго́люща: / днесь спасе́ние ми́ру, / я́ко воскре́се Христо́с, / я́ко всеси́лен. Припев:"},
  {"id": "cu-pon-0165", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pon-0166", "section": "service", "who": "choir", "text": "Му́жеский у́бо пол, / я́ко разве́рзый де́вственную утро́бу, / яви́ся Христо́с, / я́ко челове́к же, / А́гнец нарече́ся, / непоро́чен же, / я́ко невку́сен скве́рны, / на́ша Па́сха, / и я́ко Бог и́стинен / соверше́н рече́ся. Припев:"},
  {"id": "cu-pon-0167", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pon-0168", "section": "service", "who": "choir", "text": "Я́ко единоле́тный а́гнец, / благослове́нный нам вене́ц Христо́с, / во́лею за всех закла́н бысть, / Па́сха чисти́тельная, / и па́ки из гро́ба кра́сное / пра́вды нам возсия́ Со́лнце. Припев:"},
  {"id": "cu-pon-0169", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pon-0170", "section": "service", "who": "choir", "text": "Богооте́ц у́бо Дави́д / пред се́нным ковче́гом скака́ше игра́я, / лю́дие же Бо́жии святи́и, / образо́в сбытие́ зря́ще, / весели́мся Боже́ственне, / я́ко воскре́се Христо́с, / я́ко Всеси́лен."},
  {"id": "cu-pon-0171", "section": "service", "who": "choir", "text": "Слава: Созда́вый Ада́ма, Твоего́ пра́отца, Чи́стая, / зи́ждется от Тебе́, и сме́ртное жили́ще разори́ Свое́ю сме́ртию днесь, / и озари́ вся / боже́ственными блиста́ньми Воскресе́ния."},
  {"id": "cu-pon-0172", "section": "service", "who": "choir", "text": "И ныне: Его́же родила́ еси́ Христа́, / прекра́сно из ме́ртвых возсия́вша, Чи́стая зря́щи, / до́брая и непоро́чная в жена́х и кра́сная, / днесь во спасе́ние всех, со апо́столы ра́дующися, / Того́ прославля́й. Катавасия:"},
  {"id": "cu-pon-0173", "section": "service", "who": "choir", "text": "На Боже́ственней стра́жи: И тропарь:"},
  {"id": "cu-pon-0174", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-pon-0175", "section": "service", "who": "choir", "text": "Песнь 5. Ирмос:"},
  {"id": "cu-pon-0176", "section": "service", "who": "choir", "text": "У́тренюем у́треннюю глубоку́, / и вме́сто ми́ра песнь принесе́м Влады́це, / и Христа́ у́зрим / пра́вды Со́лнце, / всем жизнь возсия́юща. Припев:"},
  {"id": "cu-pon-0177", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pon-0178", "section": "service", "who": "choir", "text": "Безме́рное Твое́ благоутро́бие, / а́довыми у́зами содержи́мии зря́ще, / к све́ту идя́ху Христе́, / весе́лыми нога́ми, / Па́сху хва́ляще ве́чную. Припев:"},
  {"id": "cu-pon-0179", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pon-0180", "section": "service", "who": "choir", "text": "Присту́пим свещено́снии, / исходя́щу Христу́ из гро́ба, я́ко жениху́, / и спра́зднуем любопра́зднственными чи́нми / Па́сху Бо́жию спаси́тельную."},
  {"id": "cu-pon-0181", "section": "service", "who": "choir", "text": "Слава: Просвеща́ется боже́ственными луча́ми и живоно́сными / воскресе́ния Сы́на Твоего́, Богома́ти Пречи́стая, / и ра́дости исполня́ется / благочести́вых собра́ние."},
  {"id": "cu-pon-0182", "section": "service", "who": "choir", "text": "И ныне: Не разве́рзл еси́ врата́ де́вства в воплоще́нии, / гро́ба не разруши́л еси́ печа́тей, Царю́ созда́ния, / отону́дуже воскре́сшаго Тя зря́щи / Ма́ти, ра́довашеся. Катавасия:"},
  {"id": "cu-pon-0183", "section": "service", "who": "choir", "text": "У́тренюем у́треннюю глубоку́: И тропарь:"},
  {"id": "cu-pon-0184", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-pon-0185", "section": "service", "who": "choir", "text": "Песнь 6. Ирмос:"},
  {"id": "cu-pon-0186", "section": "service", "who": "choir", "text": "Снизше́л еси́ в преиспо́дняя земли́, / и сокруши́л еси́ вереи́ ве́чныя, / содержа́щия свя́занныя, Христе́, / и тридне́вен, я́ко от ки́та Ио́на, / воскре́сл еси́ от гро́ба. Припев:"},
  {"id": "cu-pon-0187", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pon-0188", "section": "service", "who": "choir", "text": "Сохрани́в це́ла зна́мения Христе́, / воскре́сл еси́ от гро́ба, / ключи́ Де́вы не вреди́вый в рождестве́ Твое́м, / и отве́рзл еси́ нам ра́йския две́ри. Припев:"},
  {"id": "cu-pon-0189", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pon-0190", "section": "service", "who": "choir", "text": "Спа́се мой, / живо́е же и неже́ртвенное заколе́ние, / я́ко Бог Сам Себе́ / во́лею приве́л Отцу́, / совоскреси́л еси́ всеро́днаго Ада́ма, / воскре́с от гро́ба."},
  {"id": "cu-pon-0191", "section": "service", "who": "choir", "text": "Слава: Возведе́ся дре́вле держи́мое сме́ртию и тле́нием, / воплоти́вшимся от Твоего́ пречи́стаго чре́ва, / к нетле́нней и присносу́щней жи́зни, / Богоро́дице Де́во."},
  {"id": "cu-pon-0192", "section": "service", "who": "choir", "text": "И ныне: Сни́де в преиспо́дняя земли́, / в ложесна́ Твоя́, Чи́стая, сше́дый, / и всели́выйся и воплоти́выйся па́че ума́, / и воздви́же с Собо́ю Ада́ма, / воскре́с от гро́ба. Катавасия:"},
  {"id": "cu-pon-0193", "section": "service", "who": "choir", "text": "Снизше́л еси́ в преиспо́дняя земли́: И тропарь:"},
  {"id": "cu-pon-0194", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-pon-0195", "section": "service", "who": "choir", "text": "Ектениа."},
  {"id": "cu-pon-0196", "section": "service", "who": "choir", "text": "Таже кондак, глас 8:"},
  {"id": "cu-pon-0197", "section": "service", "who": "choir", "text": "А́ще и во гроб снизше́л еси́, Безсме́ртне, / но а́дову разруши́л еси́ си́лу, / и воскре́сл еси́, я́ко победитель, Христе́ Бо́же, / жена́м мироно́сицам веща́вый: ра́дуйтеся, / и Твои́м апо́столом мир да́руяй, / па́дшим подая́й воскресе́ние. Икос:"},
  {"id": "cu-pon-0198", "section": "service", "who": "choir", "text": "Е́же пре́жде со́лнца Со́лнце заше́дшее иногда́ во гроб, / предвари́ша ко у́тру, и́щущия я́ко дне мироно́сицы де́вы, / и друга́ ко друзе́й вопия́ху: / о други́ни! Прииди́те, воня́ми пома́жем те́ло живоно́сное и погребе́ное, / плоть воскреси́вшаго па́дшаго Ада́ма, лежа́щую во гро́бе. / И́дем, потщи́мся я́коже волсви́, и поклони́мся, / и принесе́м мира я́ко да́ры, не в пелена́х, но в плащани́це обви́тому, / и пла́чим, и возопии́м: о Влады́ко, воста́ни, / па́дшим подая́й воскресе́ние."},
  {"id": "cu-pon-0199", "section": "service", "who": "choir", "text": "И чтение."},
  {"id": "cu-pon-0200", "section": "service", "who": "choir", "text": "Таже глаголем:"},
  {"id": "cu-pon-0201", "section": "service", "who": "choir", "text": "Воскресе́ние Христо́во ви́девше, / поклони́мся Свято́му Го́споду Иису́су, / еди́ному безгре́шному, / Кресту́ Твоему́ покланя́емся, Христе́, / и свято́е Воскресе́ние Твое́ пое́м и сла́вим: / Ты бо еси́ Бог наш, / ра́зве Тебе́ ино́го не зна́ем, / и́мя Твое́ имену́ем. / Прииди́те вси ве́рнии, / поклони́мся Свято́му Христо́ву Воскресе́нию: / се бо прии́де Кресто́м ра́дость всему́ ми́ру. / Всегда́ благословя́ще Го́спода, / пое́м Воскресе́ние Его́: / распя́тие бо претерпе́в, / сме́ртию смерть разруши́. [Трижды.]"},
  {"id": "cu-pon-0202", "section": "service", "who": "choir", "text": "Воскре́с Иису́с от гро́ба, / я́коже прорече́, / даде́ нам живо́т ве́чный / и ве́лию ми́лость. [Трижды.]"},
  {"id": "cu-pon-0203", "section": "service", "who": "choir", "text": "Песнь 7. Ирмос:"},
  {"id": "cu-pon-0204", "section": "service", "who": "choir", "text": "О́троки от пе́щи изба́вивый, / быв Челове́к, / стра́ждет я́ко сме́ртен, / и стра́стию сме́ртное, / в нетле́ния облачи́т благоле́пие, / Еди́н благослове́н / отце́в Бог, и препросла́влен. Припев:"},
  {"id": "cu-pon-0205", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pon-0206", "section": "service", "who": "choir", "text": "Жены́ с ми́ры богому́дрыя в след Тебе́ теча́ху, / Его́же, я́ко ме́ртва, со слеза́ми иска́ху, / поклони́шася ра́дующияся Живо́му Бо́гу, / и Па́сху та́йную / Твои́м, Христе́, ученико́м благовести́ша. Припев:"},
  {"id": "cu-pon-0207", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pon-0208", "section": "service", "who": "choir", "text": "Сме́рти пра́зднуем умерщвле́ние, / а́дово разруше́ние, / ино́го жития́ ве́чнаго нача́ло, / и игра́юще пое́м Вино́внаго, / Еди́наго благослове́ннаго / отце́в Бо́га, и препросла́вленнаго. Припев:"},
  {"id": "cu-pon-0209", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pon-0210", "section": "service", "who": "choir", "text": "Я́ко вои́стинну свяще́нная, / и всепра́зднственная сия́ спаси́тельная нощь, / и светоза́рная, / светоно́снаго дне, / воста́ния су́щи провозве́стница, / в не́йже безле́тный Свет из гро́ба пло́тски всем возсия́."},
  {"id": "cu-pon-0211", "section": "service", "who": "choir", "text": "Слава: Умертви́в Сын Твой смерть, Всенепоро́чная, / днесь всем сме́ртным пребыва́ющий живо́т во ве́ки веко́в дарова́, / Еди́н благослове́нный, / отце́в Бог и Препросла́вленный."},
  {"id": "cu-pon-0212", "section": "service", "who": "choir", "text": "И ныне: Всем ца́рствуяй созда́нием, / быв челове́к, / всели́ся в Твою́, Богоблагода́тная, утро́бу, / и распя́тие претерпе́в и смерть, / воскре́се боголе́пно, / совозста́вив нас, я́ко всеси́лен. Катавасия:"},
  {"id": "cu-pon-0213", "section": "service", "who": "choir", "text": "О́троки от пе́щи изба́вивый: И тропарь:"},
  {"id": "cu-pon-0214", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-pon-0215", "section": "service", "who": "choir", "text": "Песнь 8. Ирмос:"},
  {"id": "cu-pon-0216", "section": "service", "who": "choir", "text": "Сей нарече́нный и святы́й день, / Еди́н суббо́т Царь и Госпо́дь, / пра́здников пра́здник / и торжество́ есть торже́ств, / во́ньже благослови́м Христа́ во ве́ки. Припев:"},
  {"id": "cu-pon-0217", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pon-0218", "section": "service", "who": "choir", "text": "Прииди́те, но́ваго виногра́да рожде́ния, / Боже́ственнаго весе́лия, / в наро́читом дни Воскресе́ния, / Ца́рствия Христо́ва приобщи́мся, / пою́ще Его́ / я́ко Бо́га во ве́ки. Припев:"},
  {"id": "cu-pon-0219", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pon-0220", "section": "service", "who": "choir", "text": "Возведи́ о́крест о́чи твои́, Сио́не, и виждь: / се бо приидо́ша к тебе́, / я́ко богосве́тлая свети́ла, / от за́пада, и се́вера, и мо́ря, / и восто́ка ча́да твоя́, / в тебе́ благословя́щая Христа́ во ве́ки. Припев:"},
  {"id": "cu-pon-0221", "section": "service", "who": "choir", "text": "Пресвята́я Тро́ице, Бо́же наш, сла́ва Тебе́. Троичен:"},
  {"id": "cu-pon-0222", "section": "service", "who": "choir", "text": "О́тче Вседержи́телю, и Сло́ве, и Ду́ше, / треми́ соединя́емое во Ипоста́сех Естество́, / Пресу́щественне и Пребоже́ственне, / в Тя крести́хомся, / и Тя благослови́м во вся ве́ки."},
  {"id": "cu-pon-0223", "section": "service", "who": "choir", "text": "Благослови́м Отца́ и Сы́на и Свята́го Ду́ха, Го́спода."},
  {"id": "cu-pon-0224", "section": "service", "who": "choir", "text": "Прии́де Тобо́ю в мир Госпо́дь, / Де́во Богоро́дице, / и чре́во а́дово расто́рг, / сме́ртным нам воскресе́ние дарова́, / те́мже благослови́м Его́ во ве́ки."},
  {"id": "cu-pon-0225", "section": "service", "who": "choir", "text": "И ны́не и при́сно и во ве́ки веко́в, ами́нь."},
  {"id": "cu-pon-0226", "section": "service", "who": "choir", "text": "Всю низложи́в сме́рти держа́ву / Сын Твой, Де́во, Свои́м воскресе́нием, / я́ко Бог кре́пкий совознесе́ нас и обожи́, / те́мже воспева́ем Его́ во ве́ки. Катавасия:"},
  {"id": "cu-pon-0227", "section": "service", "who": "choir", "text": "Сей нарече́нный и святы́й день: И тропарь:"},
  {"id": "cu-pon-0228", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-pon-0229", "section": "service", "who": "choir", "text": "Песнь 9."},
  {"id": "cu-pon-0230", "section": "service", "who": "deacon", "text": "Вели́чит душа́ моя́ / Воскре́сшаго тридне́вно от гро́ба, / Христа́ Жизнодавца."},
  {"id": "cu-pon-0231", "section": "service", "who": "rubric", "text": "И первый лик ирмос:"},
  {"id": "cu-pon-0232", "section": "service", "who": "choir", "text": "Свети́ся, свети́ся, / но́вый Иерусали́ме, / сла́ва бо Госпо́дня / на тебе́ возсия́. / Лику́й ны́не / и весели́ся, Сио́не. / Ты же, Чи́стая, красу́йся, Богоро́дице, / о воста́нии Рождества́ Твоего́."},
  {"id": "cu-pon-0233", "section": "service", "who": "rubric", "text": "Таже вторый лик поет вторый припев:"},
  {"id": "cu-pon-0234", "section": "service", "who": "choir", "text": "Вели́чит душа́ моя́ / во́лею страда́вша, и погребе́на, / и Воскре́сшаго тридне́вно от гро́ба. И ирмос:"},
  {"id": "cu-pon-0235", "section": "service", "who": "choir", "text": "Свети́ся, свети́ся:"},
  {"id": "cu-pon-0236", "section": "service", "who": "rubric", "text": "Таже первый лик поет:"},
  {"id": "cu-pon-0237", "section": "service", "who": "choir", "text": "Христо́с но́вая Па́сха, / Же́ртва жива́я, / А́гнец Бо́жий, / взе́мляй грехи́ ми́ра."},
  {"id": "cu-pon-0238", "section": "service", "who": "choir", "text": "О, Боже́ственнаго, о любе́знаго, / о сладча́йшаго Твоего́ гла́са! / С на́ми бо нело́жно / обеща́лся еси́ бы́ти, / до сконча́ния ве́ка, Христе́: / Его́же, ве́рнии, / утвержде́ние наде́жди иму́ще, ра́дуемся."},
  {"id": "cu-pon-0239", "section": "service", "who": "choir", "text": "И вторый лик поет тойже припев и тропарь."},
  {"id": "cu-pon-0240", "section": "service", "who": "rubric", "text": "Таже первый лик поет припев:"},
  {"id": "cu-pon-0241", "section": "service", "who": "choir", "text": "А́нгел вопия́ше Благода́тней: / Чи́стая Де́во, ра́дуйся! / И па́ки реку́: ра́дуйся! / Твой Сын воскре́се / тридне́вен от гро́ба, / и ме́ртвыя воздви́гнувый: / лю́дие, весели́теся. И тропарь:"},
  {"id": "cu-pon-0242", "section": "service", "who": "choir", "text": "О, Боже́ственнаго, о любе́знаго:"},
  {"id": "cu-pon-0243", "section": "service", "who": "choir", "text": "И вторый лик поет тойже припев и тропарь."},
  {"id": "cu-pon-0244", "section": "service", "who": "rubric", "text": "Таже первый лик:"},
  {"id": "cu-pon-0245", "section": "service", "who": "choir", "text": "Возбуди́л еси́ усну́в ме́ртвыя от ве́ка, / ца́рски рыка́вый я́ко от Иу́ды лев. И тропарь:"},
  {"id": "cu-pon-0246", "section": "service", "who": "choir", "text": "О, Боже́ственнаго, о любе́знаго:"},
  {"id": "cu-pon-0247", "section": "service", "who": "rubric", "text": "Вторый лик:"},
  {"id": "cu-pon-0248", "section": "service", "who": "choir", "text": "Магдали́на Мари́я притече́ ко гро́бу, / и Христа́ ви́девши, / я́ко вертогра́даря вопроша́ше."},
  {"id": "cu-pon-0249", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая, Христе́! / О му́дросте, и Сло́ве Бо́жий, и си́ло! / Подава́й нам и́стее Тебе́ причаща́тися, / в невече́рнем дни Ца́рствия Твоего́."},
  {"id": "cu-pon-0250", "section": "service", "who": "rubric", "text": "Таже первый лик:"},
  {"id": "cu-pon-0251", "section": "service", "who": "choir", "text": "А́нгел облиста́яй жена́м вопия́ше: / преста́ните от слез, я́ко Христо́с воскре́се. И тропарь:"},
  {"id": "cu-pon-0252", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая:"},
  {"id": "cu-pon-0253", "section": "service", "who": "rubric", "text": "Вторый лик:"},
  {"id": "cu-pon-0254", "section": "service", "who": "choir", "text": "Христо́с воскре́се, смерть попра́вый, / и ме́ртвыя воздви́гнувый, / лю́дие весели́теся. И тропарь:"},
  {"id": "cu-pon-0255", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая:"},
  {"id": "cu-pon-0256", "section": "service", "who": "rubric", "text": "Первый лик:"},
  {"id": "cu-pon-0257", "section": "service", "who": "choir", "text": "Днесь вся́ка тварь весели́тся и ра́дуется, / я́ко Христо́с воскре́се, и ад плени́ся. И тропарь:"},
  {"id": "cu-pon-0258", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая:"},
  {"id": "cu-pon-0259", "section": "service", "who": "rubric", "text": "Вторый лик:"},
  {"id": "cu-pon-0260", "section": "service", "who": "choir", "text": "Днесь Влады́ка плени́ а́да, / воздви́гнувый ю́зники, я́же от ве́ка имя́ше лю́те одержи́мыя. И тропарь:"},
  {"id": "cu-pon-0261", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая:"},
  {"id": "cu-pon-0262", "section": "service", "who": "rubric", "text": "Первый лик:"},
  {"id": "cu-pon-0263", "section": "service", "who": "choir", "text": "Вели́чит душа́ моя́ / Триипоста́снаго и Неразде́льнаго Божества́ держа́ву."},
  {"id": "cu-pon-0264", "section": "service", "who": "choir", "text": "Согла́сно Де́во, Тебе́ блажи́м ве́рнии: / ра́дуйся, Две́ре Госпо́дня, / ра́дуйся, Гра́де одушевле́нный, / ра́дуйся, Ея́же ра́ди нам ны́не возсия́ свет, / из Тебе́ Рожде́ннаго из ме́ртвых Воскресе́ния."},
  {"id": "cu-pon-0265", "section": "service", "who": "rubric", "text": "Вторый лик:"},
  {"id": "cu-pon-0266", "section": "service", "who": "choir", "text": "Ра́дуйся, Де́во, ра́дуйся, / ра́дуйся, Благослове́нная, / ра́дуйся, Препросла́вленная! / Твой бо Сын воскре́се тридне́вен от гро́ба."},
  {"id": "cu-pon-0267", "section": "service", "who": "choir", "text": "Весели́ся и ра́дуйся боже́ственная Две́ре Све́та, / заше́дый бо Иису́с во гроб возсия́, / просия́в со́лнца светле́е, / и ве́рныя вся озари́в, / Богора́дованная Влады́чице."},
  {"id": "cu-pon-0268", "section": "service", "who": "rubric", "text": "Таже оба лика, сошедшеся вкупе, поют припев:"},
  {"id": "cu-pon-0269", "section": "service", "who": "choir", "text": "Вели́чит душа́ моя́ / Воскре́сшаго тридне́вно от гро́ба, / Христа́ Жизнодавца. И ирмос:"},
  {"id": "cu-pon-0270", "section": "service", "who": "choir", "text": "Свети́ся, свети́ся, / но́вый Иерусали́ме, / сла́ва бо Госпо́дня / на тебе́ возсия́. / Лику́й ны́не / и весели́ся, Сио́не. / Ты же, Чи́стая, красу́йся, Богоро́дице, / о воста́нии Рождества́ Твоего́. И тропарь:"},
  {"id": "cu-pon-0271", "section": "service", "who": "choir", "text": "Христо́с воскре́се:"},
  {"id": "cu-pon-0272", "section": "service", "who": "rubric", "text": "трижды. И ектениа."},
  {"id": "cu-pon-0273", "section": "service", "who": "choir", "text": "Ексапостиларий. Самогласен:"},
  {"id": "cu-pon-0274", "section": "service", "who": "choir", "text": "Пло́тию усну́в, / я́ко мертв, / Царю́ и Го́споди, / тридне́вен воскре́сл еси́, / Ада́ма воздви́г от тли, / и упраздни́в смерть, / Па́сха нетле́ния, / ми́ра спасе́ние. [Трижды.]"},
  {"id": "cu-pon-0275", "section": "service", "who": "choir", "text": "На хвалитех, Всякое дыхание: Поставим стихи 4, и поем стихиры воскресны, глас 2: Стих:"},
  {"id": "cu-pon-0276", "section": "service", "who": "choir", "text": "Хвали́те Его́ на си́лах Его́, / хвали́те Его́ по мно́жеству вели́чествия Его́."},
  {"id": "cu-pon-0277", "section": "service", "who": "choir", "text": "Вся́кое дыха́ние и вся тварь / Тя сла́вит, Го́споди, / я́ко Кресто́м смерть упраздни́л еси́, / да пока́жеши лю́дем, е́же из ме́ртвых Твое́ Воскресе́ние, / я́ко Еди́н Человеколю́бец. Стих:"},
  {"id": "cu-pon-0278", "section": "service", "who": "choir", "text": "Хвали́те Его́ во гла́се тру́бнем, / хвалите Его́ во псалти́ри и гу́слех."},
  {"id": "cu-pon-0279", "section": "service", "who": "choir", "text": "Да реку́т иуде́е, / ка́ко во́ини погуби́ша стрегу́щии Царя́? / Почто́ бо ка́мень не сохрани́ Ка́мене жи́зни? / Или́ Погребе́ннаго да дадя́т, / или́ Воскре́сшему да покло́нятся, / глаго́люще с на́ми: / сла́ва мно́жеству щедро́т Твои́х, Спа́се наш, сла́ва Тебе́. Стих:"},
  {"id": "cu-pon-0280", "section": "service", "who": "choir", "text": "Хвали́те Его́ в тимпа́не и ли́це, / хвали́те Его́ во стру́нах и орга́не."},
  {"id": "cu-pon-0281", "section": "service", "who": "choir", "text": "Ра́дуйтеся лю́дие и весели́теся, / А́нгел седя́й на ка́мени гро́бнем, / той нам благовести́, рек: / Христо́с воскре́се из ме́ртвых, Спас мiра, / и испо́лни вся́ческая благоуха́ния, / ра́дуйтеся лю́дие и весели́теся. Стих:"},
  {"id": "cu-pon-0282", "section": "service", "who": "choir", "text": "Хвали́те Его́ в кимва́лех доброгла́сных, хвали́те Его́ в кимва́лех восклица́ния, / вся́кое дыха́ние да хва́лит Го́спода."},
  {"id": "cu-pon-0283", "section": "service", "who": "choir", "text": "А́нгел у́бо е́же ра́дуйся, / пре́жде Твоего́ зача́тия, Го́споди, Благода́тней принесе́, / А́нгел же ка́мень сла́внаго Твоего́ гро́ба / в Твое́ Воскресе́ние отвали́. / Ов у́бо в печа́ли ме́сто, / весе́лия о́бразы возвеща́я, / сей же в сме́рти ме́сто, / Влады́ку Жизнода́вца пропове́дуя нам, / те́мже вопие́м Ти: / Благоде́телю всех, Го́споди, сла́ва Тебе́."},
  {"id": "cu-pon-0284", "section": "service", "who": "choir", "text": "И стихиры Пасхи с припевы их, глас 5. Стих:"},
  {"id": "cu-pon-0285", "section": "service", "who": "choir", "text": "Да воскре́снет Бог, / и расточа́тся врази́ Его́."},
  {"id": "cu-pon-0286", "section": "service", "who": "choir", "text": "Па́сха / свяще́нная нам днесь показа́ся; / Па́сха но́ва свята́я; / Па́сха та́инственная; / Па́сха всечестна́я. / Па́сха Христо́с Изба́витель; / Па́сха непоро́чная; / Па́сха вели́кая; / Па́сха ве́рных. / Па́сха две́ри ра́йския нам отверза́ющая. / Па́сха всех освяща́ющая ве́рных. Стих:"},
  {"id": "cu-pon-0287", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, / да исче́знут."},
  {"id": "cu-pon-0288", "section": "service", "who": "choir", "text": "Прииди́те / от виде́ния жены́ благове́стницы, / и Сио́ну рцы́те: / приими́ / от нас ра́дости благове́щения, Воскресе́ния Христо́ва: / красу́йся, лику́й / и ра́дуйся, Иерусали́ме, / Царя́ Христа́ узре́в из гро́ба, / я́ко жениха́ происходя́ща. Стих:"},
  {"id": "cu-pon-0289", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся."},
  {"id": "cu-pon-0290", "section": "service", "who": "choir", "text": "Мироно́сицы жены́, / у́тру глубоку́, / предста́вша гро́бу Живода́вца, / обрето́ша А́нгела / на ка́мени седя́ща, / и той провеща́в им, / си́це глаго́лаше: / что и́щете Жива́го с ме́ртвыми; / что пла́чете Нетле́ннаго во тли? / Ше́дше, пропове́дите ученико́м Его́. Стих:"},
  {"id": "cu-pon-0291", "section": "service", "who": "choir", "text": "Сей день, его́же сотвори Госпо́дь, / возра́дуемся и возвесели́мся в онь."},
  {"id": "cu-pon-0292", "section": "service", "who": "choir", "text": "Па́сха кра́сная, / Па́сха, Госпо́дня Па́сха! / Па́сха всечестна́я / нам возсия́. Па́сха, / ра́достию друг дру́га обы́мем. / О Па́сха! / Избавле́ние ско́рби, / и́бо из гро́ба днесь, / я́ко от черто́га / возсия́в Христо́с, / жены́ ра́дости испо́лни, глаго́ля: / пропове́дите апо́столом."},
  {"id": "cu-pon-0293", "section": "service", "who": "choir", "text": "Слава, и ныне, глас 5: Воскресе́ния день, / и просвети́мся торжество́м, / и друг дру́га обы́мем. / Рцем бра́тие, / и ненави́дящим нас, / прости́м вся Воскресе́нием, / и та́ко возопии́м: / Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в, / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pon-0294", "section": "service", "who": "choir", "text": "Таже настоящий тропарь, во глас 5, трижды:"},
  {"id": "cu-pon-0295", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pon-0296", "section": "service", "who": "choir", "text": "И ектении, и отпуст. И час 1-й. Сице же бывает служба Утрени во всю седмицу Светлую. Творим же и литию вне обители."},
  {"id": "cu-pon-0297", "section": "service", "who": "rubric", "text": "Подобает ведати, я́ко творим исхождение днесь вне монастыря, предносяще хоругви. В руках же держаще святое Евангелие, честный Крест, и иконы Воскресе́ния Христо́ва, Пречистыя Богоро́дицы. Поем канон Пасхи с Богородичны, на 8. И Катавасия, ирмос тойже. По 6-й песни, последи Евангелиа глаголем:"},
  {"id": "cu-pon-0298", "section": "service", "who": "choir", "text": "Воскресе́ние Христо́во ви́девше:"},
  {"id": "cu-pon-0299", "section": "service", "who": "rubric", "text": "трижды. Таже, стихира:"},
  {"id": "cu-pon-0300", "section": "service", "who": "choir", "text": "Воскрес Иису́с от гро́ба:"},
  {"id": "cu-pon-0301", "section": "service", "who": "rubric", "text": "трижды. Таже, 7-я, 8-я и 9-я песни. И прочее молебна."},
  {"id": "cu-pon-0302", "section": "service", "who": "choir", "text": "НА ЛИТУРГИИ"},
  {"id": "cu-pon-0303", "section": "service", "who": "rubric", "text": "Наченшу диакону:"},
  {"id": "cu-pon-0304", "section": "service", "who": "deacon", "text": "Благослови́ влады́ко."},
  {"id": "cu-pon-0305", "section": "service", "who": "rubric", "text": "Настоятелю же возгласившу:"},
  {"id": "cu-pon-0306", "section": "service", "who": "deacon", "text": "Благослове́но Ца́рство Отца́ и Сы́на и Свята́го Ду́ха, ны́не и при́сно и во ве́ки веко́в. И мы:"},
  {"id": "cu-pon-0307", "section": "service", "who": "deacon", "text": "Ами́нь."},
  {"id": "cu-pon-0308", "section": "service", "who": "deacon", "text": "Настоятель поет с прочими служители во святом олтаре:"},
  {"id": "cu-pon-0309", "section": "service", "who": "deacon", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в, / и су́щим во гробе́х живо́т дарова́в. Трижды."},
  {"id": "cu-pon-0310", "section": "service", "who": "deacon", "text": "И лики тойжде, трижды."},
  {"id": "cu-pon-0311", "section": "service", "who": "choir", "text": "Настоятель глаголет припевы: Первый стих:"},
  {"id": "cu-pon-0312", "section": "service", "who": "choir", "text": "Да воскре́снет Бог, и расточа́тся врази́ Его́, / и да бежа́т от Лица́ Его́ ненави́дящии Его́."},
  {"id": "cu-pon-0313", "section": "service", "who": "choir", "text": "И на кийждо стих мы поем тропарь весь по единожды: Тропарь:"},
  {"id": "cu-pon-0314", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды. Вторый стих:"},
  {"id": "cu-pon-0315", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, да исче́знут, / я́ко та́ет воск от лица́ огня́. Тропарь:"},
  {"id": "cu-pon-0316", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды. Третий стих:"},
  {"id": "cu-pon-0317", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся. Тропарь:"},
  {"id": "cu-pon-0318", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-pon-0319", "section": "service", "who": "rubric", "text": "Четвертый стих:"},
  {"id": "cu-pon-0320", "section": "service", "who": "choir", "text": "Сей день, его́же сотвори́ Госпо́дь, / возра́дуемся и возвесели́мся в онь. Тропарь:"},
  {"id": "cu-pon-0321", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-pon-0322", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху. Тропарь:"},
  {"id": "cu-pon-0323", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-pon-0324", "section": "service", "who": "choir", "text": "И ны́не и при́сно и во ве́ки веко́в. Ами́нь. Тропарь:"},
  {"id": "cu-pon-0325", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-pon-0326", "section": "service", "who": "rubric", "text": "Таже настоятель поет вышшим гласом:"},
  {"id": "cu-pon-0327", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в. Мы же:"},
  {"id": "cu-pon-0328", "section": "service", "who": "choir", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pon-0329", "section": "service", "who": "choir", "text": "Посем глаголет диакон ектению великую. По ектении же и по возгласе:"},
  {"id": "cu-pon-0330", "section": "service", "who": "choir", "text": "Антифон первый, псалом 65, глас 2. Стих 1:"},
  {"id": "cu-pon-0331", "section": "service", "who": "choir", "text": "Воскли́кните Го́сподеви / вся земля́. Припев:"},
  {"id": "cu-pon-0332", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас."},
  {"id": "cu-pon-0333", "section": "service", "who": "rubric", "text": "И другий лик тойжде стих:"},
  {"id": "cu-pon-0334", "section": "service", "who": "choir", "text": "Воскли́кните Го́сподеви вся земля́, / по́йте же и́мени Его́, дади́те сла́ву хвале́ Его́. Припев:"},
  {"id": "cu-pon-0335", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас. Стих 2:"},
  {"id": "cu-pon-0336", "section": "service", "who": "choir", "text": "Рцы́те Бо́гу: коль стра́шна дела́ Твоя́, / во мно́жестве си́лы Твоея́ со́лжут Тебе́ врази́ Твои́. Припев:"},
  {"id": "cu-pon-0337", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас. Стих 3:"},
  {"id": "cu-pon-0338", "section": "service", "who": "choir", "text": "Вся земля́ да покло́нится Тебе́, / и пое́т Тебе́, да пое́т же и́мени Твоему́ Вы́шний. Припев:"},
  {"id": "cu-pon-0339", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас."},
  {"id": "cu-pon-0340", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху, / и ны́не и при́сно и во ве́ки веко́в. Ами́нь."},
  {"id": "cu-pon-0341", "section": "service", "who": "rubric", "text": "Купно оба лика вышшим гласом:"},
  {"id": "cu-pon-0342", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас."},
  {"id": "cu-pon-0343", "section": "service", "who": "choir", "text": "Таже, ектениа малая."},
  {"id": "cu-pon-0344", "section": "service", "who": "choir", "text": "Антифон вторый, псалом 66, глас тойже. Стих 1:"},
  {"id": "cu-pon-0345", "section": "service", "who": "choir", "text": "Бо́же уще́дри ны / и благослови́ ны. Припев:"},
  {"id": "cu-pon-0346", "section": "service", "who": "choir", "text": "Спаси́ ны, Сы́не Бо́жий, / воскресы́й из ме́ртвых, пою́щия Ти: / Аллилу́иа. Единожды."},
  {"id": "cu-pon-0347", "section": "service", "who": "rubric", "text": "Другая страна, тойже стих:"},
  {"id": "cu-pon-0348", "section": "service", "who": "choir", "text": "Бо́же, уще́дри ны и благослови́ ны, / просвети лице Твое́ на ны и поми́луй ны. Припев:"},
  {"id": "cu-pon-0349", "section": "service", "who": "choir", "text": "Спаси́ ны, Сы́не Бо́жий, / воскресы́й из ме́ртвых, пою́щия Ти: / Аллилу́иа. Единожды. Стих 2:"},
  {"id": "cu-pon-0350", "section": "service", "who": "choir", "text": "Да позна́ем на земли́ путь Твой, / во всех язы́цех спасе́ние Твое́. Припев:"},
  {"id": "cu-pon-0351", "section": "service", "who": "choir", "text": "Спаси́ ны, Сы́не Бо́жий, / воскресы́й из ме́ртвых, пою́щия Ти: / Аллилу́иа. Единожды. Стих 3:"},
  {"id": "cu-pon-0352", "section": "service", "who": "choir", "text": "Да испове́дятся Тебе́ лю́дие, Бо́же, / да испове́дятся Тебе́ лю́дие вси. Припев:"},
  {"id": "cu-pon-0353", "section": "service", "who": "choir", "text": "Спаси́ ны, Сы́не Бо́жий, / воскресы́й из ме́ртвых, пою́щия Ти: / Аллилу́иа. Единожды."},
  {"id": "cu-pon-0354", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху, / и ны́не и при́сно и во ве́ки веко́в. Ами́нь."},
  {"id": "cu-pon-0355", "section": "service", "who": "rubric", "text": "Вкупе два лика:"},
  {"id": "cu-pon-0356", "section": "service", "who": "choir", "text": "Единоро́дный Сы́не и Сло́ве Бо́жий, Безсме́ртен Сый / и изво́ливый спасе́ния на́шего ра́ди / воплоти́тися от Святы́я Богоро́дицы и Присноде́вы Мари́и, / непрело́жно вочелове́чивыйся, / распны́йся же, Христе́ Бо́же, сме́ртию смерть попра́вый, / Еди́н Сый Святы́я Тро́ицы, / спрославля́емый Отцу́ и Свято́му Ду́ху, спаси́ нас."},
  {"id": "cu-pon-0357", "section": "service", "who": "choir", "text": "Таже, ектениа."},
  {"id": "cu-pon-0358", "section": "service", "who": "choir", "text": "Антифон 3-й, псалом 67, глас 5. Стих 1:"},
  {"id": "cu-pon-0359", "section": "service", "who": "choir", "text": "Да воскре́снет Бог / и расточа́тся врази́ Его́."},
  {"id": "cu-pon-0360", "section": "service", "who": "choir", "text": "Тропарь, глас 5: Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pon-0361", "section": "service", "who": "rubric", "text": "Другая страна, той же стих:"},
  {"id": "cu-pon-0362", "section": "service", "who": "choir", "text": "Да воскре́снет Бог и расточа́тся врази́ Его́, / и да бежа́т от лица́ Его́ ненави́дящии Его́. Тропарь:"},
  {"id": "cu-pon-0363", "section": "service", "who": "choir", "text": "Христо́с воскре́се: Стих 2:"},
  {"id": "cu-pon-0364", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, да исче́знут, / я́ко та́ет воск от лица́ огня́. Тропарь:"},
  {"id": "cu-pon-0365", "section": "service", "who": "choir", "text": "Христо́с воскре́се: Стих 3:"},
  {"id": "cu-pon-0366", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от лица́ Бо́жия, / а пра́ведницы да возвеселя́тся, да возра́дуются пред Бо́гом. Тропарь:"},
  {"id": "cu-pon-0367", "section": "service", "who": "choir", "text": "Христо́с воскре́се:"},
  {"id": "cu-pon-0368", "section": "service", "who": "rubric", "text": "И бывает вход. И возглашает диакон, аще есть, аще же ни, иерей:"},
  {"id": "cu-pon-0369", "section": "service", "who": "deacon", "text": "Прему́дрость, про́сти."},
  {"id": "cu-pon-0370", "section": "service", "who": "deacon", "text": "Мы же входное: В це́рквах благослови́те Бо́га, / Го́спода от исто́чник Изра́илевых."},
  {"id": "cu-pon-0371", "section": "service", "who": "deacon", "text": "И поем тропарь, глас 5: Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pon-0372", "section": "service", "who": "deacon", "text": "Ипакои, глас 4: Предвари́вшия у́тро, я́же о Мари́и, / и обре́тшия ка́мень отвале́н от гро́ба, / слы́шаху от А́нгела: во све́те присносу́щнем Су́щаго / с ме́ртвыми что и́щете, я́ко челове́ка? / Ви́дите гро́бныя пелены́, тецы́те и ми́ру пропове́дите, / я́ко воста́ Госпо́дь, умертви́вый смерть, / я́ко есть Сын Бо́га, спаса́ющаго род челове́ческий."},
  {"id": "cu-pon-0373", "section": "service", "who": "deacon", "text": "Слава, и ныне: кондак, глас 8: А́ще и во гроб снизше́л еси́, Безсме́ртне, / но а́дову разруши́л еси́ си́лу, / и воскре́сл еси́, я́ко Победи́тель, Христе́ Бо́же, / жена́м мироно́сицам веща́вый: ра́дуйтеся! / И Твои́м апо́столом мир да́руяй, / па́дшим подая́й воскресе́ние."},
  {"id": "cu-pon-0374", "section": "service", "who": "deacon", "text": "Вместо же Трисвятаго: Ели́цы во Христа́ крести́стеся, / во Христа́ облеко́стеся: / аллилу́иа."},
  {"id": "cu-pon-0375", "section": "service", "who": "deacon", "text": "Прокимен Апостола, глас 8: Во всю зе́млю изы́де веща́ние их, / и в концы́ вселе́нныя глаго́лы их. Стих:"},
  {"id": "cu-pon-0376", "section": "service", "who": "deacon", "text": "Небеса́ пове́дают сла́ву Бо́жию, творе́ние же руку́ Его́ возвеща́ет твердь."},
  {"id": "cu-pon-0377", "section": "service", "who": "deacon", "text": "Деяния святых Апостол, зачало 2."},
  {"id": "cu-pon-0378", "section": "service", "who": "deacon", "text": "Во дни о́ны, возврати́шася апо́столи во Иерусали́м от горы́ нарица́емыя Елео́н, я́же есть близ Иерусали́ма, суббо́ты иму́щия путь. И егда́ внидо́ша, взыдо́ша на го́рницу, иде́же бя́ху пребыва́юще, Петр же и Иа́ков, и Иоа́нн, и Андре́й, Фили́пп и Фома́, Варфоломе́й и Матфе́й, Иа́ков Алфе́ов и Си́мон Зило́т, и Иу́да Иа́ковль. Си́и вси бя́ху терпя́ще единоду́шно в моли́тве и моле́нии, с жена́ми и Мари́ею Ма́терию Иису́совою, и с бра́тиею Его́. И во дни ты́я воста́в Петр посреде́ учени́к, рече́, бе же име́н наро́да вку́пе я́ко сто и два́десять: му́жие бра́тие, подоба́ше сконча́тися Писа́нию сему́, е́же предрече́ Дух Святы́й усты́ Дави́довыми о Иу́де, бы́вшем вожди́ е́мшим Иису́са, я́ко причте́н бе с на́ми и прия́л бя́ше жре́бий слу́жбы сея́. Подоба́ет у́бо от сходи́вшихся с на́ми муже́й во вся́ко ле́то, в не́же вни́де и изы́де в нас Госпо́дь Иису́с, наче́н от креще́ния Иоа́ннова да́же до дне, во́ньже вознесе́ся (на не́бо) от нас, свиде́телю воскресе́ния Его́ бы́ти с на́ми еди́ному от сих. И поста́виша два, Ио́сифа нарица́емаго Варса́ву, и́же нарече́н бысть Иу́ст, и Матфи́а. И помоли́вшеся ре́ша: Ты, Го́споди, Сердцеве́дче всех, покажи́, его́же избра́л еси́ от сею́ двою́ еди́наго, прия́ти жре́бий служе́ния сего́ и апо́стольства, из него́же испаде́ Иу́да, ити́ в ме́сто свое́. И да́ша жре́бия и́ма, и паде́ жре́бий на Матфи́а, и причте́н бысть ко единона́десяти апо́столом."},
  {"id": "cu-pon-0379", "section": "service", "who": "deacon", "text": "Аллилуиа, глас 1: Стих:"},
  {"id": "cu-pon-0380", "section": "service", "who": "deacon", "text": "Испове́дят небеса́ чудеса́ Твоя́, Го́споди. Стих:"},
  {"id": "cu-pon-0381", "section": "service", "who": "deacon", "text": "Бог прославля́емь в сове́те святы́х."},
  {"id": "cu-pon-0382", "section": "service", "who": "deacon", "text": "Евангелие от Иоанна, зачало 2."},
  {"id": "cu-pon-0383", "section": "service", "who": "deacon", "text": "Бо́га никто́же ви́де нигде́же: Единоро́дный Сын, сый в ло́не О́тчи, Той испове́да. И сие́ есть свиде́тельство Иоа́нново, егда́ посла́ша жи́дове от Иерусали́ма иере́ев и леви́тов, да вопро́сят его́: ты кто еси́? И испове́да и не отве́ржеся: и испове́да, я́ко несмь аз Христо́с. И вопроси́ша его́: что у́бо? Илиа́ ли еси́ ты? И глаго́ла: несмь. Проро́к ли еси́? И отвеща́: ни. Ре́ша же ему́: кто еси́? Да отве́т да́мы посла́вшим ны. Что глаго́леши о тебе́ само́м? Рече́: аз глас вопию́щаго в пусты́ни, испра́вите путь Госпо́день, я́коже рече́ Иса́иа проро́к. И по́сланнии бе́ху от фарисе́й. И вопроси́ша его́ и ре́ша ему́: что у́бо креща́еши, а́ще ты не́си Христо́с, ни Илиа́, ни проро́к? Отвеща́ им Иоа́нн, глаго́ля: аз креща́ю водо́ю, посреде́ же вас стои́т, Его́же вы не ве́сте. Той есть Гряды́й по мне, И́же предо мно́ю бысть, Ему́же несмь аз досто́ин, да отрешу́ реме́нь сапогу́ Его́. Сия́ в Вифава́ре бы́ша об он пол Иорда́на, иде́же бе Иоа́нн крестя́."},
  {"id": "cu-pon-0384", "section": "service", "who": "deacon", "text": "И бывает по чину Божественная Литургиа Златоустаго."},
  {"id": "cu-pon-0385", "section": "service", "who": "deacon", "text": "Вместо же Достойно: поем: А́нгел вопия́ше Благода́тней: / Чи́стая Де́во, ра́дуйся! / И па́ки реку́: ра́дуйся! / Твой Сын воскре́се / тридне́вен от гро́ба, / и ме́ртвыя воздви́гнувый, / лю́дие, весели́теся."},
  {"id": "cu-pon-0386", "section": "service", "who": "rubric", "text": "Таже ирмос, глас 1:"},
  {"id": "cu-pon-0387", "section": "service", "who": "deacon", "text": "Свети́ся, свети́ся, / но́вый Иерусали́ме, / сла́ва бо Госпо́дня / на тебе́ возсия́. / Лику́й ны́не / и весели́ся, Сио́не. / Ты же, Чи́стая, красу́йся, Богоро́дице, / о воста́нии Рождества́ Твоего́."},
  {"id": "cu-pon-0388", "section": "service", "who": "deacon", "text": "Причастный: Те́ло Христо́во приими́те, / исто́чника безсме́ртнаго вкуси́те. / Аллилу́иа. трижды."},
  {"id": "cu-pon-0389", "section": "service", "who": "rubric", "text": "Егда же настоятель глаголет:"},
  {"id": "cu-pon-0390", "section": "service", "who": "deacon", "text": "Со стра́хом Бо́жиим и ве́рою приступи́те."},
  {"id": "cu-pon-0391", "section": "service", "who": "rubric", "text": "Мы вместо, Благословен грядый во имя Господне: поем:"},
  {"id": "cu-pon-0392", "section": "service", "who": "deacon", "text": "Христо́с воскре́се:"},
  {"id": "cu-pon-0393", "section": "service", "who": "rubric", "text": "единожды. Настоятель глаголет:"},
  {"id": "cu-pon-0394", "section": "service", "who": "deacon", "text": "Спаси́ Бо́же лю́ди Твоя́: И мы:"},
  {"id": "cu-pon-0395", "section": "service", "who": "deacon", "text": "Христо́с воскре́се:"},
  {"id": "cu-pon-0396", "section": "service", "who": "rubric", "text": "единожды. Егда же изглаголет иерей:"},
  {"id": "cu-pon-0397", "section": "service", "who": "priest", "text": "Всегда́ ны́не и при́сно: И мы:"},
  {"id": "cu-pon-0398", "section": "service", "who": "priest", "text": "Христо́с воскре́се:"},
  {"id": "cu-pon-0399", "section": "service", "who": "rubric", "text": "единожды. Посем ектениа. Вместо же, Буди имя Господне: и вместо псалма, Благословлю Господа: поем:"},
  {"id": "cu-pon-0400", "section": "service", "who": "priest", "text": "Христо́с воскре́се:"},
  {"id": "cu-pon-0401", "section": "service", "who": "rubric", "text": "дванадесять, и множае: дондеже анафора от игумена раздастся. Таже настоятель,"},
  {"id": "cu-pon-0402", "section": "service", "who": "priest", "text": "Благослове́ние Госпо́дне на вас:"},
  {"id": "cu-pon-0403", "section": "service", "who": "choir", "text": "Ами́нь."},
  {"id": "cu-pon-0404", "section": "service", "who": "rubric", "text": "Посем настоятель вместо, Слава Тебе Христе Боже: поет:"},
  {"id": "cu-pon-0405", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в."},
  {"id": "cu-pon-0406", "section": "service", "who": "rubric", "text": "И лик:"},
  {"id": "cu-pon-0407", "section": "service", "who": "choir", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pon-0408", "section": "service", "who": "rubric", "text": "Посем настоятель глаголет отпуст со Крестом по обычаю."},
  {"id": "cu-pon-0409", "section": "service", "who": "choir", "text": "На трапезе бывает утешение великое братии."},
];

